    /* SHIFT (semitones) and FOLOW (key tracking around C4, fixed), one ratio for all four */
    ratio = fmt_ratio(p[P_E3] * 16 + ((30 * (v->pitch_cur - 60 * 16) * 516) >> 16)); /* FOLOW / 127 */
    bws = fmt_ratio((64 - p[P_E6]) * 4); /* Q: bandwidth x2.5 .. x0.4 */
