static uint32_t ds_inc(int32_t p16) { return PITCH_INC[clamp(p16, 0, 127 * 16 + 15)]; }
static uint16_t ds_blocks(uint32_t units2ms) { return (uint16_t)(units2ms * 2u * 44100 / 1000u / 32); }
