static int32_t drum_set(void)
{
    uint32_t i;
    if (PKV(37).set == -2) {
        PKV(37).set = -1;
        for (i = 0; i < 5; i++)
            if (str_eq(SMP_SETS[i].name, "PERC"))
                PKV(37).set = (int16_t)i;
    }
    return PKV(37).set;
}
/* a free voice, else the oldest (its last value fades: no click); the hi-hat choke first */
static voice_t *drum_voice(uint32_t note)
{
    voice_t *v = &PKV(37).v[0];
    uint32_t i;
    if (note == 35u || note == 36u)
        PKV(37).kick = 1;
    if (note == 42u || note == 44u) /* hi-hat choke */
        for (i = 0; i < 6; i++)
            if (PKV(37).v[i].active && PKV(37).v[i].note == 46u) {
                PKV(37).v[i].active = 0;
                PKV(37).tail += PKV(37).v[i].s[7];
            }
    for (i = 0; i < 6; i++) {
        if (!PKV(37).v[i].active)
            return &PKV(37).v[i];
        if (PKV(37).v[i].age < v->age)
            v = &PKV(37).v[i];
    }
    PKV(37).tail += v->s[7];
    return v;
}
static void drum_on(uint32_t note, uint32_t vel)
{
    int32_t si = drum_set();
    const smp_set_t *set;
    voice_t *v = &PKV(37).v[0];
    uint32_t i, zi = 0xFFFFu, kit = drum_kit();
    if (kit) { /* Jangada: a synthesised kit */
        v = drum_voice(note);
        i = (uint32_t)(v - PKV(37).v);
        v->note = (uint8_t)note;
        v->vel = (uint8_t)vel;
        v->active = 1;
        v->s[7] = 0;
        v->age = ++PKV(37).age;
        PKV(37).synth[i] = 1;
        ds_on(&PKV(37).ds[i], &DS_KITS[kit - 1u], note, vel);
        return;
    }
    if (si < 0)
        return;
    set = &SMP_SETS[si];
    zi = smp_zone_pick(set, note);
    if (zi == 0xFFFFu)
        return;
    if (note == 35u || note == 36u)
        PKV(37).kick = 1;
    if (note == 42u || note == 44u) /* hi-hat choke */
        for (i = 0; i < 6; i++)
            if (PKV(37).v[i].active && PKV(37).v[i].note == 46u) {
                PKV(37).v[i].active = 0;
                PKV(37).tail += PKV(37).v[i].s[7]; /* fade what it was playing, not a step */
            }
    for (i = 0; i < 6; i++) { /* free voice, else the oldest */
        if (!PKV(37).v[i].active) {
            v = &PKV(37).v[i];
            break;
        }
        if (PKV(37).v[i].age < v->age)
            v = &PKV(37).v[i];
    }
    if (v->active)
        PKV(37).tail += v->s[7]; /* stolen voice: fade its last value */
    v->note = (uint8_t)note;
    v->vel = (uint8_t)vel;
    v->active = 1;
    v->s[7] = 0;
    v->age = ++PKV(37).age;
    v->s[4] = (int32_t)zi;
    v->ph[0] = v->ph[1] = 0;
    v->s[0] = v->s[1] = v->s[2] = 0;
    v->s[3] = sample_next(&SMP_ZONES[zi], v, 0);
    v->s[5] = (int32_t)((pow2_q16((int32_t)note * 16 - SMP_ZONES[zi].root16) >> 8) * (SMP_ZONES[zi].rate >> 8));
    PKV(37).synth[v - PKV(37).v] = 0;
}
/* adds the drums into the dry mix and the reverb send; mono != 0: into mono instead, before the
 * pan and the send (the SLICER, slicer.c slicer_drums, does those after it) */
static inline void drums_mix(int32_t *ml, int32_t *mr, int32_t *rev, int32_t *mono, uint32_t n)
{
    uint32_t k, i;
    int32_t lvl = PKV(3).g[G_DRLVL] * 200, send = thr_send(PKV(3).g[G_DRREV] * 258, 0), pk = PKV(37).peak;
    int32_t pan = PKV(2)[3].p[P_PAN], gl = 4096 - (pan > 0 ? pan * 64 : 0), gr = 4096 + (pan < 0 ? pan * 64 : 0);
    for (i = 0; i < n && PKV(37).tail; i++) { /* declick tail, ~0.4 ms */
        if (mono) {
            mono[i] += PKV(37).tail;
        } else {
            ml[i] += PKV(37).tail;
            mr[i] += PKV(37).tail;
        }
        PKV(37).tail -= PKV(37).tail / 16 + (PKV(37).tail > 0 ? 1 : PKV(37).tail < 0 ? -1 : 0);
    }
    for (k = 0; k < 6; k++) { /* Jangada: synthesised voices (they peak ~1.75 x the GM
                                                     * samples, as SLOOP measured: brought to the same level) */
        voice_t *v = &PKV(37).v[k];
        uint32_t m = n < 32 ? n : 32;
        int32_t gs = (lvl * 4681) >> 13;
        if (!v->active || !PKV(37).synth[k])
            continue;
        if (!ds_render(&PKV(37).ds[k], PKV(38), m))
            v->active = 0;
        for (i = 0; i < m; i++) {
            int32_t s = mulq15(PKV(38)[i], gs);
            v->s[7] = s;
            if (s > pk || -s > pk)
                pk = s < 0 ? -s : s;
            if (mono) {
                mono[i] += s;
                continue;
            }
            ml[i] += (s * gl) >> 12;
            mr[i] += (s * gr) >> 12;
            if (send)
                rev[i] += mulq15(s, send);
        }
    }
    for (k = 0; k < 6; k++) {
        voice_t *v = &PKV(37).v[k];
        const smp_zone_t *z = &SMP_ZONES[v->s[4]];
        uint32_t frac = v->ph[1], stepq = (uint32_t)v->s[5]; /* Q16 source samples per output (drum_on) */
        int32_t g;
        if (!v->active || PKV(37).synth[k])
            continue;
        g = mulq15(lvl, v->vel * 258);
        for (i = 0; i < n; i++) {
            int32_t s;
            frac += stepq;
            while (frac >= 65536u) {
                frac -= 65536u;
                v->s[2] = v->s[3];
                if (v->ph[0] >= z->n) {
                    v->active = 0;
                    break;
                }
                v->s[3] = sample_next(z, v, 0);
            }
            if (!v->active)
                break;
            s = v->s[2] + (((v->s[3] - v->s[2]) * (int32_t)(frac >> 1)) >> 15);
            s = mulq15(s, g);
            v->s[7] = s;
            if (s > pk || -s > pk)
                pk = s < 0 ? -s : s;
            if (mono) {
                mono[i] += s;
                continue;
            }
            ml[i] += (s * gl) >> 12;
            mr[i] += (s * gr) >> 12;
            if (send)
                rev[i] += mulq15(s, send);
        }
        v->ph[1] = frac;
    }
    PKV(37).peak = pk;
}
static void drums_render(int32_t *ml, int32_t *mr, int32_t *rev, uint32_t n) { drums_mix(ml, mr, rev, 0, n); }
static void drums_render_mono(int32_t *mono, uint32_t n) { drums_mix(0, 0, 0, mono, n); }
