/* the INSERT's A B C as its TYPE means them (TP's ranges and defaults): the drives DRIVE TONE LEVEL, CRUSH BITS RATE
 * LPF, the swept ones RATE DEPTH FDBK; OFF: TP's own */
static const param_desc_t INS_DESC[4][3] = {
    {{"DRIVE", F_PCT, 0, 127, 64, 0, 0}, {"TONE", F_CUTOFF, 0, 127, 96, 0, 0}, {"LEVEL", F_DB, 0, 127, 96, 0, 0}},
    {{"BITS", F_INT, 0, 127, 64, N_IBITS, 0}, {"RATE", F_INT, 0, 127, 96, N_IRATE, "Hz"}, {"LPF", F_CUTOFF, 0, 127, 96, 0, 0}},
    {{"RATE", F_LFOHZ, 0, 127, 64, 0, 0}, {"DEPTH", F_PCT, 0, 127, 96, 0, 0}, {"FDBK", F_PCT, 0, 127, 96, 0, 0}},
    {{"AMNT", F_PCT, 0, 127, 64, 0, 0}, {"STRCH", F_INT, 0, 127, 96, N_IBITS, 0}, {"FDBK", F_PCT, 0, 127, 96, 0, 0}}, /* DISP */
};
static const param_desc_t *ins_desc(int32_t type, uint32_t k)
{
    if (type <= 0 || type >= (int32_t)(sizeof N_ITYPE / sizeof N_ITYPE[0]))
        return &TP[P_IA + k];
    return &INS_DESC[type < 5 ? 0 : type == 5 ? 1 : type < 9 ? 2 : 3][k]; /* (IT_SOFT .. IT_FUZZ, IT_CRUSH, the swept
                                                                                * ones, IT_DISP) */
}
static const param_desc_t *track_desc(const track_t *t, uint32_t id)
{
    if (id >= P_E0 && id < P_E0 + 16) { /* the engine asked for (t->engine follows after a fade) */
        const engine_t *e = ENGINES[t->eng_req % (13 + 0)];
        const param_desc_t *d = e->desc ? e->desc(t, id - P_E0) : 0; /* a mode-dependent label / names */
        return d ? d : &e->edit[id - P_E0];
    }
    if (id == P_M1DST || id == P_M2DST || id == P_M3DST || id == P_M4DST)
        return mod_dst_desc(ENGINES[t->eng_req % (13 + 0)]);
    if (id == P_DIST && t->p[P_DTYPE] > 0) { /* Jangada GRIT: DIST is named by its type (FX page) */
        static const param_desc_t DIST_AS[4] = {{"FUZZ", F_PCT, 0, 127, 0, 0, 0}, {"FOLD", F_PCT, 0, 127, 0, 0, 0},
                                                {"CRUSH", F_PCT, 0, 127, 0, 0, 0}, {"RING", F_PCT, 0, 127, 0, 0, 0}};
        return &DIST_AS[(t->p[P_DTYPE] - 1) & 3];
    }
    if (id >= P_IA && id <= P_IC) /* the INSERT's values as its TYPE names them */
        return ins_desc(t->p[P_ITYPE], id - P_IA);
    if (t->p[P_ESYNC] && (id == P_ATK || id == P_DEC || id == P_REL)) { /* ESYNC: note values (voice.c) */
        static const param_desc_t ES_D[3] = {{"ATK", F_ESYNC, 0, 127, 10, 0, 0}, {"DEC", F_ESYNC, 0, 127, 70, 0, 0},
                                             {"REL", F_ESYNC, 0, 127, 60, 0, 0}};
        return &ES_D[id == P_ATK ? 0 : id == P_DEC ? 1 : 2];
    }
    return &TP[id];
}
/* Jangada 0.9.7 ESYNC (after Felucca 1.5): ATK, DEC and REL as note values of the tempo, 1/64T .. 4 bars with
 * the dotted and triplet ones; a knob value 0..127 is one of the 21 (presets keep their numbers). Their length
 * in 1/96 of a beat */
static const char *const ES_NAME[21u] = {"1/64T", "1/64", "1/32T", "1/32", "1/16T", "1/32D", "1/16", "1/8T",
                                          "1/16D", "1/8", "1/4T", "1/8D", "1/4", "1/2T", "1/4D", "1/2", "1/2D",
                                          "1/1", "1/1D", "2BAR", "4BAR"};
static const uint16_t ES_U96[21u] = {4, 6, 8, 12, 16, 18, 24, 32, 36, 48, 64, 72, 96, 128, 144, 192, 288, 384,
                                      576, 768, 1536};
static uint32_t es_index(int32_t v) { return (uint32_t)clamp(v, 0, 127) * (21u - 1u) / 127u; }
/* value string (<= 5 chars) and unit for a parameter value */
static void param_format(const param_desc_t *d, int32_t v, char *val, const char **unit)
{
    *unit = "";
    switch (d->fmt) {
    case F_PCT:
        fmt_int(val, (v * 100 + 63) / 127);
        *unit = "%";
        break;
    case F_BIPCT:
        fmt_int(val, v * 100 / 64);
        if (v > 0) {
            char t[8];
            fmt_int(t, v * 100 / 64);
            val[0] = '+';
            str_cpy(val + 1, t, 6);
        }
        *unit = "%";
        break;
    case F_ESYNC: /* Jangada 0.9.7: an envelope time as a note value */
        str_cpy(val, ES_NAME[es_index(v)], 6);
        *unit = "";
        break;
    case F_TIME: {
        uint32_t ms10 = TIME_MS_X10[v & 127];
        if (ms10 < 100u) {
            fmt_fix(val, (int32_t)ms10, 1);
            *unit = "ms";
        } else if (ms10 < 10000u) {
            fmt_int(val, (int32_t)((ms10 + 5u) / 10u));
            *unit = "ms";
        } else {
            fmt_fix(val, (int32_t)(ms10 / 100u), 2);
            if (ms10 >= 100000u)
                fmt_fix(val, (int32_t)(ms10 / 1000u), 1);
            *unit = "s";
        }
        break;
    }
    case F_LFOHZ: {
        uint32_t h = LFO_HZ_X100[v & 127];
        if (h < 1000u)
            fmt_fix(val, (int32_t)h, 2);
        else
            fmt_fix(val, (int32_t)(h / 10u), 1);
        *unit = "Hz";
        break;
    }
    case F_CUTOFF: {
        uint32_t h = CUTOFF_HZ[v & 127];
        if (h < 1000u) {
            fmt_int(val, (int32_t)h);
            *unit = "Hz";
        } else {
            fmt_fix(val, (int32_t)(h / 100u), 1);
            *unit = "kHz";
        }
        break;
    }
    case F_DB:
        if (v <= 0) {
            str_cpy(val, "OFF", 6);
        } else {
            fmt_fix(val, LEVEL_DB_X10[v], 1);
            *unit = "dB";
        }
        break;
    case F_SEMI:
        fmt_int(val, v);
        if (v > 0) {
            char t[8];
            fmt_int(t, v);
            val[0] = '+';
            str_cpy(val + 1, t, 6);
        }
        *unit = "st";
        break;
    case F_ENUM:
        str_cpy(val, d->names[v < d->min ? d->min : v > d->max ? d->max : v], 6);
        if (d->unit)
            *unit = d->unit;
        break;
    case F_BPM:
        fmt_int(val, v);
        *unit = "BPM";
        break;
    case F_NOTE:
        str_cpy(val, N_NOTE[v % 12], 6);
        break;
    case F_ONOFF:
        str_cpy(val, N_ONOFF[v ? 1 : 0], 6);
        break;
    case F_STEPS:
        fmt_int(val, v);
        *unit = "STEP";
        break;
    case F_FILT: /* LP 0..100 closing, HP 0..100 opening */
        if (!v) {
            str_cpy(val, "OFF", 6);
        } else {
            str_cpy(val, v < 0 ? "LP" : "HP", 6);
            fmt_int(val + 2, v < 0 ? (-v * 100 + 32) / 64 : (v * 100 + 31) / 63);
        }
        break;
    default:
        if (d->names) { /* F_INT with a 0-terminated name list: the range */
            uint32_t k = 0; /* split evenly over the names (engine desc hooks) */
            while (d->names[k])
                k++;
            str_cpy(val, d->names[(uint32_t)(clamp(v, d->min, d->max) - d->min) * k / (uint32_t)(d->max - d->min + 1)], 6);
        } else {
            fmt_int(val, v);
        }
        if (d->unit)
            *unit = d->unit;
        break;
    }
}
