/* the drum track has no sound of its own: it uses the global pages (not the preset
 * pages, nor TOOLS > INIT: page_desc), STEP, PATTERN, SLICER and TRACKS; every other page
 * shows "DRUM TRACK" */
static int page_for_drum(const page_t *pg)
{
    if (pg->scope == SC_GLOBAL)
        return pg->graph != GR_BROWSE && pg->graph != GR_USER;
    return pg->scope != SC_ENGINE && (pg->scope != SC_TRACK || pg->fam == FAM_SEQ || pg->graph == GR_SLCR);
}
/* Jangada: an EDIT page is shown only when the engine has a parameter on it (EDIT 3 / 4:
 * engines with more than 8) */
static int page_used(uint32_t pi)
{
    const page_t *pg = &PAGES[pi];
    const engine_t *e = ENGINES[(&PKV(2)[PKV(3).sel])->eng_req % (13 + 0)];
    uint32_t k;
    if (pg->scope != SC_ENGINE)
        return 1;
    for (k = 0; k < 4u; k++)
        if (pg->id[k] >= P_E0 && pg->id[k] < P_E0 + 16 && e->edit[pg->id[k] - P_E0].label)
            return 1;
    return 0;
}
static const param_desc_t *page_desc(const page_t *pg, uint32_t slot, int16_t **valp)
{
    static const param_desc_t BEAT_D = {"BEAT", F_ENUM, 0, (int16_t)(sizeof(N_BEAT) / sizeof(N_BEAT[0]) - 1), 0, N_BEAT, 0};
    uint32_t id = pg->id[slot];
    if (id == 0xFEu) { /* Jangada: not saved; turning it loads a beat */
        *valp = &PKV(37).beat;
        return &BEAT_D;
    }
    if (id == 0xFFu || (is_drum((&PKV(2)[PKV(3).sel])) && (!page_for_drum(pg) || (pg->scope == SC_GLOBAL && id == G_INITSND)))) {
        *valp = 0;
        return 0;
    }
    if (pg->scope == SC_STEP || pg->scope == SC_TRK) {
        *valp = 0;
        return 0;
    }
    if (pg->scope == SC_GLOBAL) {
        *valp = &PKV(3).g[id];
        return &GP[id];
    }
    *valp = &(&PKV(2)[PKV(3).sel])->p[id];
    return track_desc((&PKV(2)[PKV(3).sel]), id);
}
