    t->dist_hp = hp;
    t->dist_lp1 = t->dist_lp2 = t->dist_x1 = t->dist_x2 = 0;
    dist_run(t, b, n, mode, d);
    step = 32768 / (int32_t)(n ? n : 1u);
    for (i = 0; i < (int32_t)n; i++) {
        int32_t g = i * step; /* 0 .. ~1, Q15 */
        b[i] = PKV(52)[i] + ((((b[i] - PKV(52)[i]) >> 3) * (g >> 3)) >> 9);
    }
