        int32_t s = sine_i(ph), c = clamp(s * 3, -32767, 32767), x, y;
        uint32_t nz = noise32(&PKV(56).rnd);
        ph += 5843375u;
        if ((nz >> 10) < pc)
            PKV(56).pop = (int32_t)(nz & 0x7FFu) - 1024; /* a crackle */
        PKV(56).ll += ((((int32_t)(nz >> 16) - 32768) >> 6) + PKV(56).pop - PKV(56).ll) >> 1; /* hiss, ~5 kHz */
        PKV(56).lr += ((((int32_t)(nz & 0xFFFFu) - 32768) >> 6) + PKV(56).pop - PKV(56).lr) >> 1;
        PKV(56).pop -= PKV(56).pop >> 3;
        s = ((s + c * 3) * 11) >> 10; /* the hum: +-1400 at full */
