static int32_t crush_bits(int32_t v, int32_t shift) /* fewer bits, rounded toward 0: no DC from tails */
{
    return v >= 0 ? (v >> shift) << shift : -((-v >> shift) << shift);
}
static void dust_process(int32_t *l, int32_t *r, uint32_t n)
{
    int32_t d = PKV(3).g[G_DUST], hold, shift, a, drive, hiss, i, bed0, bed1;
    uint32_t pc;
    if (!d) {
        PKV(81).bed = 0;
        return;
    }
    hold = 1 + d * 3 / 127;
    shift = d / 18;
    a = 32767 - d * 165; /* one-pole coefficient, Q15 */
    drive = 4096 + d * 24; /* Q12: 1x .. 1.75x */
    hiss = d * 2;
    pc = (uint32_t)d * 7u; /* crackle: chance per sample, x 2^-22 */
    bed0 = PKV(81).bed; /* ~0.1 s from 0 to full (238 a block of 32) */
    bed1 = PKV(81).bed = clamp(PKV(81).bed + (PKV(3).playing ? 238 : -238), 0, 32767);
    for (i = 0; i < (int32_t)n; i++) {
        int32_t x = l[i], y = r[i];
        int32_t bed = bed0 + (((bed1 - bed0) * i) >> 5);
        uint32_t nz = noise32(&PKV(81).rnd);
        if (--PKV(81).hn <= 0) { /* sample and hold, then the bits */
            PKV(81).hn = hold;
            PKV(81).hl = softclip(((x >> 2) * drive) >> 10);
            PKV(81).hr = softclip(((y >> 2) * drive) >> 10);
            if (shift) {
                PKV(81).hl = crush_bits(PKV(81).hl, shift);
                PKV(81).hr = crush_bits(PKV(81).hr, shift);
            }
        }
        PKV(81).ll += mulq15(PKV(81).hl - PKV(81).ll, a);
        PKV(81).lr += mulq15(PKV(81).hr - PKV(81).lr, a);
        if ((nz >> 10) < pc) /* a speck of dust */
            PKV(81).click = mulq15(((int32_t)(nz & 0x3FFu) - 512) * d / 8, bed);
        x = PKV(81).ll + PKV(81).click + mulq15(((int32_t)(nz >> 16) - 32768) * hiss >> 15, bed);
        y = PKV(81).lr + PKV(81).click + mulq15(((int32_t)(nz & 0xFFFFu) - 32768) * hiss >> 15, bed);
        PKV(81).click -= PKV(81).click >> 2;
        l[i] = x;
        r[i] = y;
    }
}
static void djf_process(int32_t *l, int32_t *r, uint32_t n)
{
    tsvf_t c;
    if (!djf_block(&PKV(76), PKV(3).g[G_FILT], &c))
        return;
    djf_run(&PKV(76), &c, l, n, 0, 0);
    djf_run(&PKV(76), &c, r, n, 1, 0);
}
/* SPDX-License-Identifier: GPL-3.0-only
 * From SLOOP 2.2 (isod89/sloop-fm1, GPL-3.0), a Felucca fork; ported to Jangada unchanged but for
 * the clock (fx.c clk_pos) and the keys (seq.c keyboard_block, ui_input.c). */
/* PUNCH-IN FX, pocket-operator style: hold FX, press a white key (16 of them, F3..G5) and the
 * whole mix goes through that effect while the key is held; release it and the mix comes
 * back. Beat-synced to the tempo; loops start on the grid of the running transport.
 * A mono ring of the mix (PUNCH_N samples, 0.74 s) feeds the loops, reverse, tape stop,
 * half speed, wobble and echo; the filters, crush and gate run in stereo. Every change
 * crossfades over 64 samples. Runs in the audio ISR (mix_block, fx.c). */
