    int last;
    for (i = 0; i < n; i++)
        PKV(90)[i] = PKV(93).e0_src[i];
    fm1_usb_ep0_send(PKV(90), n);
    PKV(93).e0_src += n;
    PKV(93).e0_left = (uint16_t)(PKV(93).e0_left - n);
    last = PKV(93).e0_left == 0 && !(n == 64u && PKV(93).e0_zlp);
    if (PKV(93).e0_left == 0 && n == 64u)
        PKV(93).e0_zlp = 0;
    sie_wr(S_INDEX, 0);
    sie_wr(S_CSR0, last ? 0x0A : 0x02);
    if (last)
        PKV(93).e0_tx = 0;
