        if (PKV(93).config == 1u)
            ep1_config();
        else
            sie_wr(S_INTRRX1E, 0);
        goto ack;
    case 0x8008:
        e0_send(&PKV(93).config, 1, wlength);
        return;
    case 0x8000:
    case 0x8100:
    case 0x8200:
        e0_send(zero2, 2, wlength);
        return;
    case 0x010B: /* SET_INTERFACE: alt 0 (alt 1 for the audio stream) */
        if (wvalue == 0)
            goto ack;
        goto stall;
    case 0x810A:
        e0_send(zero2, 1, wlength);
        return;
